const response = $input.first().json;
const content = response.content;
if (!content || !content[0] || !content[0].text) {
  throw new Error('Claude returned empty response for Owner Manual generation');
}

const markdownContent = content[0].text;

// Wrap markdown in clean HTML for PDF generation
const htmlDoc = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>IntraWeb OS Owner's Manual</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { font-family: 'Georgia', serif; color: #1a1a1a; line-height: 1.7; padding: 60px 72px; font-size: 13px; }
    h1 { font-size: 28px; font-weight: 700; color: #0d1b2a; margin-bottom: 8px; border-bottom: 3px solid #0d1b2a; padding-bottom: 12px; }
    h2 { font-size: 20px; font-weight: 700; color: #0d1b2a; margin-top: 40px; margin-bottom: 12px; border-bottom: 1px solid #d0d0d0; padding-bottom: 8px; }
    h3 { font-size: 15px; font-weight: 700; color: #2c3e50; margin-top: 24px; margin-bottom: 8px; }
    p { margin-bottom: 12px; }
    ul, ol { margin-left: 24px; margin-bottom: 12px; }
    li { margin-bottom: 4px; }
    code { font-family: 'Courier New', monospace; background: #f4f4f4; padding: 2px 5px; border-radius: 3px; font-size: 12px; }
    pre { background: #f4f4f4; border-left: 4px solid #0d1b2a; padding: 16px; margin: 16px 0; font-family: 'Courier New', monospace; font-size: 11px; white-space: pre-wrap; }
    table { width: 100%; border-collapse: collapse; margin: 16px 0; font-size: 12px; }
    th { background: #0d1b2a; color: white; padding: 8px 10px; text-align: left; font-weight: 600; }
    td { padding: 7px 10px; border-bottom: 1px solid #e8e8e8; vertical-align: top; }
    tr:nth-child(even) td { background: #f9f9f9; }
    strong, b { font-weight: 700; color: #0d1b2a; }
    .cover-page { text-align: center; padding: 120px 60px; page-break-after: always; }
    .cover-title { font-size: 36px; font-weight: 900; color: #0d1b2a; margin-bottom: 16px; }
    .cover-subtitle { font-size: 18px; color: #555; margin-bottom: 48px; }
    .cover-meta { font-size: 13px; color: #888; }
    @media print { body { padding: 40px 54px; } }
  </style>
</head>
<body>
  <div class="cover-page">
    <div class="cover-title">IntraWeb OS</div>
    <div class="cover-subtitle">Owner's Manual</div>
    <div class="cover-subtitle" style="font-size:14px; color:#333;">IntraWeb Technologies LLC<br>AI Automation Operating System</div>
    <div class="cover-meta">Generated: ${new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })}<br>14 Automated Systems | Full Stack Operations Reference</div>
  </div>
  <div id="content">
    ${markdownContent
      .replace(/^# (.*$)/gm, '<h1>$1</h1>')
      .replace(/^## (.*$)/gm, '<h2>$1</h2>')
      .replace(/^### (.*$)/gm, '<h3>$1</h3>')
      .replace(/^#### (.*$)/gm, '<h4 style="font-size:13px;font-weight:700;margin-top:16px;margin-bottom:6px;">$1</h4>')
      .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
      .replace(/`([^`]+)`/g, '<code>$1</code>')
      .replace(/^\* (.+)$/gm, '<li>$1</li>')
      .replace(/^- (.+)$/gm, '<li>$1</li>')
      .replace(/^\d+\. (.+)$/gm, '<li>$1</li>')
      .replace(/\n\n/g, '</p><p>')
      .replace(/^(?!<[h|l|p|u|o])/gm, '')
    }
  </div>
</body>
</html>`;

return [{ json: { html: htmlDoc, markdown: markdownContent, timestamp: new Date().toISOString() } }];

const uploadResponse = $input.first().json;
const fileId = uploadResponse.id;
const fileName = uploadResponse.name || 'IntraWeb-OS-Owners-Manual.pdf';
const webViewLink = uploadResponse.webViewLink || `https://drive.google.com/file/d/${fileId}/view`;

if (!fileId) {
  throw new Error('Google Drive upload failed — no file ID returned');
}

return [{
  json: {
    file_id: fileId,
    file_name: fileName,
    drive_link: webViewLink,
    timestamp: new Date().toISOString()
  }
}];

